import React, { useState, useEffect, useContext, useCallback } from 'react';
import { Plus, Search, Edit2, Trash2, CheckCircle2 } from 'lucide-react';
import { getTasks, createTask, updateTask, deleteTask, reviewTask } from '../../services/taskService';
import { getProjects } from '../../services/projectService';
import { getUsers } from '../../services/userService';
import TaskFormModal from '../../components/tasks/TaskFormModal';
import TaskReviewModal from '../../components/tasks/TaskReviewModal';
import Badge from '../../components/common/Badge';
import Pagination from '../../components/common/Pagination';
import LoadingSpinner from '../../components/common/LoadingSpinner';
import { NotificationContext } from '../../context/NotificationContext';

const taskStatuses = ['All Statuses', 'Pending', 'In Progress', 'Submitted', 'Under Review', 'Approved', 'Rejected', 'Completed'];

const TasksPage = () => {
  const { addToast } = useContext(NotificationContext);
  const [tasks, setTasks] = useState([]);
  const [projects, setProjects] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [total, setTotal] = useState(0);
  const [pages, setPages] = useState(1);
  const [currentPage, setCurrentPage] = useState(1);

  // Filters
  const [search, setSearch] = useState('');
  const [taskStatus, setTaskStatus] = useState('');

  // Modals
  const [isFormModalOpen, setIsFormModalOpen] = useState(false);
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState(null);

  const fetchDependencies = async () => {
    try {
      const pRes = await getProjects({ limit: 100 });
      const eRes = await getUsers({ limit: 100 });
      setProjects(pRes.data);
      setEmployees(eRes.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchTasks = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getTasks({
        page: currentPage,
        search,
        taskStatus: taskStatus === 'All Statuses' ? '' : taskStatus,
        limit: 10,
      });
      setTasks(res.data);
      setTotal(res.total);
      setPages(res.pages);
    } catch (err) {
      addToast('Failed to fetch tasks', 'danger');
    } finally {
      setLoading(false);
    }
  }, [currentPage, search, taskStatus, addToast]);

  useEffect(() => {
    fetchDependencies();
  }, []);

  useEffect(() => {
    fetchTasks();
  }, [fetchTasks]);

  const handleOpenAdd = () => {
    setSelectedTask(null);
    setIsFormModalOpen(true);
  };

  const handleOpenEdit = (t) => {
    setSelectedTask(t);
    setIsFormModalOpen(true);
  };

  const handleOpenReview = (t) => {
    setSelectedTask(t);
    setIsReviewModalOpen(true);
  };

  const handleFormSubmit = async (data) => {
    try {
      if (selectedTask) {
        await updateTask(selectedTask._id, data);
        addToast('Task updated successfully', 'success');
      } else {
        await createTask(data);
        addToast('Task created & assigned successfully', 'success');
      }
      setIsFormModalOpen(false);
      fetchTasks();
    } catch (err) {
      addToast(err.response?.data?.message || 'Operation failed', 'danger');
    }
  };

  const handleReviewSubmit = async (taskId, reviewData) => {
    try {
      await reviewTask(taskId, reviewData);
      addToast(`Task submission ${reviewData.action.toLowerCase()} successfully`, 'success');
      setIsReviewModalOpen(false);
      fetchTasks();
    } catch (err) {
      addToast(err.response?.data?.message || 'Review action failed', 'danger');
    }
  };

  const handleDelete = async (id, title) => {
    if (window.confirm(`Delete task '${title}'?`)) {
      try {
        await deleteTask(id);
        addToast('Task deleted', 'success');
        fetchTasks();
      } catch (err) {
        addToast(err.response?.data?.message || 'Delete failed', 'danger');
      }
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">Task & Deliverable Management</h1>
          <p className="page-subtitle">Assign editorial tasks, set task payments, and review employee submissions</p>
        </div>
        <button className="btn btn-primary" onClick={handleOpenAdd}>
          <Plus size={18} /> Create & Assign Task
        </button>
      </div>

      <div className="search-filter-panel">
        <div className="search-input-wrapper">
          <Search className="search-icon" size={18} />
          <input
            type="text"
            className="form-input"
            placeholder="Search task title, ID, or description..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <div className="flex-row" style={{ gap: '10px' }}>
          <select className="form-select" value={taskStatus} onChange={(e) => setTaskStatus(e.target.value)}>
            {taskStatuses.map((s) => (
              <option key={s} value={s === 'All Statuses' ? '' : s}>
                {s}
              </option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <LoadingSpinner />
      ) : (
        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>Task ID</th>
                <th>Task Title</th>
                <th>Project</th>
                <th>Assigned Staff</th>
                <th>Payment</th>
                <th>Priority</th>
                <th>Status</th>
                <th>Deadline</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {tasks.length === 0 ? (
                <tr>
                  <td colSpan="9" style={{ textAlign: 'center', padding: '30px', color: 'var(--text-muted)' }}>
                    No tasks found.
                  </td>
                </tr>
              ) : (
                tasks.map((t) => (
                  <tr key={t._id}>
                    <td>
                      <strong style={{ color: 'var(--primary)' }}>{t.taskId}</strong>
                    </td>
                    <td>
                      <div style={{ fontWeight: 700 }}>{t.taskTitle}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                        Est. {t.estimatedHours} hrs | {t.progressPercentage}% Complete
                      </div>
                    </td>
                    <td>{t.project?.bookName || 'N/A'}</td>
                    <td>
                      {(t.assignedTo || []).map((u) => u.fullName).join(', ') || 'Unassigned'}
                    </td>
                    <td>
                      <strong style={{ color: 'var(--success)' }}>${t.taskPaymentAmount}</strong>
                    </td>
                    <td>
                      <Badge text={t.priority} />
                    </td>
                    <td>
                      <Badge text={t.taskStatus} />
                    </td>
                    <td>{new Date(t.deadline).toLocaleDateString()}</td>
                    <td>
                      <div className="flex-row" style={{ gap: '6px' }}>
                        {t.taskStatus === 'Submitted' && (
                          <button
                            className="btn btn-primary btn-sm"
                            onClick={() => handleOpenReview(t)}
                            title="Review Work"
                          >
                            <CheckCircle2 size={14} /> Review
                          </button>
                        )}
                        <button className="btn btn-secondary btn-sm" onClick={() => handleOpenEdit(t)}>
                          <Edit2 size={14} />
                        </button>
                        <button className="btn btn-danger btn-sm" onClick={() => handleDelete(t._id, t.taskTitle)}>
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      )}

      <Pagination currentPage={currentPage} totalPages={pages} onPageChange={(p) => setCurrentPage(p)} />

      <TaskFormModal
        isOpen={isFormModalOpen}
        onClose={() => setIsFormModalOpen(false)}
        onSubmit={handleFormSubmit}
        projects={projects}
        employees={employees}
        initialData={selectedTask}
        isEdit={!!selectedTask}
      />

      <TaskReviewModal
        isOpen={isReviewModalOpen}
        onClose={() => setIsReviewModalOpen(false)}
        onReview={handleReviewSubmit}
        task={selectedTask}
      />
    </div>
  );
};

export default TasksPage;
